Abbreviation mem := (word -> option byte).
Abbreviation IC := PMLA.C_xboth.

Module PSOP.
(* [comment removed for export] *)
Definition PT : list Z := [SKIPSP; PNULL; BOBJ; BARR; EOBJ; EARR; BMEMBER; PTRUE; PFALSE; PSTRING; PNUMBER; ENDINT; ENDFRAC].

(* [comment removed for export] *)
Definition wsb (b : Z) : bool := PSO.inb b [9; 10; 13; 32].
Definition nfin (z : Z) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S10|10;$z;R+0!2'1#1!3,2+0!1,3,4!3,2+0!1,30!3,2+0!1,3|20;!3,2+0!1,3|23;!1,5+0").
Definition rng_all (cells : list kentry) (e : expr) (f : Z -> bool) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S10!2+;+0+0$cells;R!1+6+7$e;R+8$f;R%~R+0+9-:RN$x;R!1+:0+9!2'<#3#22$p;R0-;RN$p;R!2+;+0+0+9#11$lo;R+0$hi;R+0!2'=!2'=!2'>,?#2!2'>#1!1,3|77f;!3'@+0#4!2'A#2#1,B").
(* [comment removed for export] *)
Definition lit2 (i : nat) (c : CC.cutpoint) (cells : list kentry) (t l : PSO.pv) (d : PSO.delta) : option Z :=
  match PSO.pclass i c cells t l d with Some PSO.PSame => PSO.tst c cells t | Some (PSO.PString _) => Some 15 | Some (PSO.PNumber _ _) => Some 17 | None => None end.
(* [comment removed for export] *)
Definition callee_ok (pc : Z) (ps : SR.post_spec) (cells : list kentry) (t l : PSO.pv) (d : PSO.delta) (z : Z) : bool :=
  let cur := PSO.v_wptr l in
  if Z.eqb pc SKIPSP then
    (CL.ps_reg_is ps 11 (EAlu Instr.ALU_ADD PE (ELit 200)) && PSO.expectb z && PSO.is_same (PSO.d_wptr d) && expr_eqb (PSO.v_wptr t) PSO.CURH && PSO.lo_ge cells (EVar JV) 1
     && match CAX.cell_at cells cur 0 1 with Some eb => rng_all cells eb wsb | None => false end)%bool
  else if (Z.eqb pc PNULL) then
    (CL.ps_reg_is ps 11 VE && CL.ps_reg_is ps 12 EE && PSO.expectb z && PSO.is_same (PSO.d_wptr d) && expr_eqb (PSO.v_wptr t) PSO.CURH && PSO.lo_ge cells (EVar JV) 1)%bool
  else if (Z.eqb pc PTRUE || Z.eqb pc PFALSE)%bool then
    (CL.ps_reg_is ps 11 cur && CL.ps_reg_is ps 12 VE && CL.ps_reg_is ps 13 EE && PSO.expectb z && PSO.is_same (PSO.d_wptr d) && expr_eqb (PSO.v_wptr t) PSO.CURH
     && PSO.lo_ge cells (EVar JV) 1)%bool
  else if (Z.eqb pc BOBJ || Z.eqb pc BARR || Z.eqb pc EOBJ || Z.eqb pc EARR)%bool then
    (CL.ps_reg_is ps 11 VE && CL.ps_reg_is ps 12 EE && negb (PSO.ccrb z) && negb (Z.eqb z 15))%bool
  else if Z.eqb pc BMEMBER then (CL.ps_reg_is ps 11 EE && Z.eqb z 7)%bool
  else if Z.eqb pc PSTRING then (CL.ps_reg_is ps 11 cur && CL.ps_reg_is ps 12 VE && CL.ps_reg_is ps 13 EE && Z.eqb z 15 && PSO.lo_ge cells (EVar JV) 1
                                 && (expr_eqb cur PSO.CURH || expr_eqb cur (EAlu Instr.ALU_ADD PSO.CURH (ELit 1))))%bool
  else if Z.eqb pc PNUMBER then (CL.ps_reg_is ps 11 cur && CL.ps_reg_is ps 12 VE && CL.ps_reg_is ps 13 EE && Z.eqb z 17 && expr_eqb (nth 11 (CA.ps_reglist ps) (ELit 0)) cur)%bool
  else if (Z.eqb pc ENDINT || Z.eqb pc ENDFRAC)%bool then
    (CL.ps_reg_is ps 11 VE && CL.ps_reg_is ps 12 EE && Z.eqb z 17 && PSO.is_same (PSO.d_nst d) && rng_all cells (PSO.v_nst l) nfin)%bool
  else false.
Definition ptkind (k : PSO.kind) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$k;R+C-CRN$k;R+C+9#1F,B,D,D,B,B,B,B,B,B,D,B,B,B,B,B,B,B,D,D$pc;R+0,B$pc;R+0,B,B").
(* [comment removed for export] *)
Definition plainb (z0 : Z) : bool := (negb (PSO.ccrb z0) && negb (Z.eqb z0 15) && Z.leb 1 z0 && Z.leb z0 28)%bool.
Definition src_ok (i : nat) (c : CC.cutpoint) (cells : list kentry) (t l : PSO.pv) (d : PSO.delta) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 6 "S20!1+:+0!1'Q#1$i;R+E$c;R+F$cells;R!1+6+7$t;R+G$l;R+G$d;R+H-:RN$x;R!1+:+I+9!6'J#6#5#4#3#2#12$p;R+I-IRN$p;R+I+9#13!1'K!2'L!1'M#7,N$s1;R0-9RN$~R+9+9!2'L!1'M#8,N2!2'O!1'P#8!1,3|40;-:RN$s1;R!1+:+0+9#12$z0;R+01,B$s1;R0$n;R+0-:RN$s1;R!1+:+0+9#22$z0;R+01,B,B").
Definition fdlit (f : PSO.fd) (z : Z) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$f;R+R$z;R+0-RRN$f;R+R+9#24,B$z';R+0!2'O#1#2$v;R+E,B,B").
Lemma fdlit_ok : forall f z, fdlit f z = true -> f = PSO.Lit z.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S40!1,U#4$e;R+9-9RN$b;R+9w#12+X+Y!1,U#1%~R!3+S+9!2'O#2#1,D!3+S+0#3#2$f;R+R$z;R+0$H;R!3+S+9!2'T#2#1,D!1-RRN$f;R+R%H;R!3+S+9!2'T#1#3,D!3+S+R#20#34$H;R!3+S+9!2'T,V#2,D&H0;R!6'W+9!2'T,V#31,Z,D#1+X!2'[!3+S+R,V0#1$z;R+0!1$z0;R+0$H;R!3+S+9!2'T2#4,D&H0;R$n;R+0$m;R+0!5'\3%~R!3+S+0#2#1!3+S+9!2'O#3#2,D%~R!3+S+9!2'O#2#1,D!3+S+0#3#2$~R3$~R%~R!3+S+0#3#2!3+S+9!2'O#4#3,D#2!2'^0#2#1%n;R+0%m;R+03&H;R!3#1#3#6#2!3+S+0#3#6!6'^1+0#7$z0;R+0!3+S+R2!1,U#8!2,^2+R!1,U#7#4#1#1$v;R+E!1$v;R+E$H;R!3+S+9!2'T!1,^3#1#4,D&H0;R!6'W+9!2'T!1,^3#2#51,Z,D#1+X!2'[!3+S+R!1,^3#3!1,U#6#1#1$H;R!3+S+9!2'T,^4#2,D&H0;R!6'W+9!2'T,^4#31,Z,D#1+X!2'[!3+S+R,^40#1#1").
Qed.
(* [comment removed for export] *)
Definition pcl_ok (c : CC.cutpoint) (d : PSO.delta) (p : option PSO.pcase) : bool :=
  match p with
  | Some PSO.PSame => (PSO.is_same (PSO.d_st d) && PSO.is_same (PSO.d_sst d) && PSO.is_same (PSO.d_nst d) && PSO.is_same (PSO.d_done d))%bool
  | Some (PSO.PString _) => (fdlit (PSO.d_st d) 15 && fdlit (PSO.d_sst d) 0 && PSO.is_same (PSO.d_nst d) && PSO.is_same (PSO.d_done d) && fdlit (PSO.d_size d) 0)%bool
  | Some (PSO.PNumber _ n) => (fdlit (PSO.d_st d) 17 && PSO.is_same (PSO.d_sst d) && fdlit (PSO.d_nst d) n && PSO.is_same (PSO.d_done d) && PSO.is_same (PSO.d_size d)
                               && negb (PSO.has_bufbyte (CC.cp_F c)) && Z.leb 0 n && Z.leb n 7)%bool
  | None => false
