Definition pc_fn (pc : Z) : PMW.fname :=
  if pc =? SKIPSP then PMW.FSkipSpace else if pc =? BOBJ then PMW.FBeginObject else if pc =? BARR then PMW.FBeginArray
  else if pc =? EOBJ then PMW.FEndObject else if pc =? EARR then PMW.FEndArray else if pc =? PSTRING then PMW.FParseString else if pc =? PNUMBER then PMW.FParseNumber
  else if pc =? PNULL then PMW.FParseNull else if pc =? PTRUE then PMW.FParseTrue else if pc =? PFALSE then PMW.FParseFalse
  else if pc =? BMEMBER then PMW.FBeginMember else if pc =? ENDINT then PMW.FEndInt else PMW.FEndFrac.
