(* [comment removed for export] *)
Definition pbn_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (tg : CC.tag) : bool :=
  match tg with
  | CC.TOther pc => if (PSO.inb pc PT && negb (PSO.dead_chk i ps pc) && PSO.kind_eqb (PSO.kind_of i) PSO.KPushb)%bool then
      match PSO.pview (CC.cp_know c), PSO.pview (SR.ps_cells ps) with
      | Some t, Some l => match PSO.pclass i c (SR.ps_cells ps) t l (PSO.mkdelta (SR.ps_cells ps) t l) with
                          | Some (PSO.PNumber _ _) => Z.eqb (PSO.d_adv (PSO.mkdelta (SR.ps_cells ps) t l)) 1 | _ => false end
      | _, _ => false end
    else true
  | _ => true end.
Lemma PBN_all : CH2.leaves_all G.CPS G.TAGS pbn_chk = true. Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00vv!2,^2+9,D!3+S+9!3'_E'_F'_G'b?,D").
Qed.
Lemma PBN : forall i c k ps0 pc t l, CH2.is_leaf G.CPS G.TAGS i c k ps0 (CC.TOther pc) -> In pc PT -> PSO.dead_chk i ps0 pc = false -> PSO.kind_of i = PSO.KPushb ->
  PSO.pview (CC.cp_know c) = Some t -> PSO.pview (SR.ps_cells ps0) = Some l ->
