Definition a0_ok (j : nat) : bool :=
  match PSO.kind_of j with
  | PSO.KPt pc => if PSO.is_curpc pc then
      match PSOK.xs_at pc with
      | Some xa => match CAX.xs_a0 (PSOK.x_of xa) [] (CC.cp_nx (PSO.cutn j) - 14 - APC.NCS) with Some e => expr_eqb (PSOX.a0reg j) e | None => false end
      | None => false end
      else true
  | _ => true end.
