Definition ptg (WFin : PML.pstate -> Prop) (BBin : PML.pstate -> Z -> Prop) (PAin : mem -> Z -> PML.pstate -> Prop) (PAout : PML.pstate -> mem -> Z -> PML.pstate -> Prop)
    (pc scr d : Z) (uar : bool) (Args : bvmap 5 word -> mem -> list (Z * Z) -> Z -> Z -> Z -> PML.pstate -> Prop)
    (Rel : PML.pstate -> PML.pstate -> Z -> bvmap 5 word -> Prop) (Wf : Z -> Z -> list L5.range) : Prop :=
  forall (LBo : list (Z * Z)) (FF LK : list fframe) (cr : credit) (A : list (Z * Z)) (sp r P V E B kx bx : Z) (g : PML.ls_state) (ps : PML.pstate),
    PMSA.cps_asan L ar HI pc r sp scr (PML.ps_blocks ps ++ LBo) FF LK cr A d
      (fun R M => Args R M LBo P V E ps /\ (uar = true -> sp mod 32 = 0) /\ PMSA.stksh ar M sp scr /\
                  PAin M P ps /\ PMSA.parser_sh M ps /\ WFin ps /\ PMSA.win_okA M LBo ps /\ BBin ps B /\ PMSA.vis_at L IC M V /\ PMSA.ec_at L IC M E 0 /\
                  PMSA.ls_ok L IC g M /\ g <> PML.LS0 /\
                  PMLA.pcredit_xA L cr ps kx bx /\ PMSA.fobj M FF P 272 /\ PMSA.fobj M FF V 8 /\ PMSA.fobj M FF E 16 /\
                  PMLA.apart P 272 V 8 /\ PMLA.apart P 272 E 16 /\ PMLA.apart V 8 E 16)
      (fun R M R' M' LB' cr' LBk W => exists (ps' : PML.pstate) (code : Z) (g' : PML.ls_state),
          PAout ps M' P ps' /\ PMSA.parser_sh M' ps' /\ PML.wf_ps ps' /\ PMSA.win_okA M' LBo ps' /\ PML.buf_bound ps' B /\ PMSA.ec_at L IC M' E code /\
          (code <> 0 -> PML.ps_more ps' = false) /\
          PMSA.ls_ok L IC g' M' /\ (g' = g \/ (g' = PML.LS2 /\ code <> 0)) /\
          LB' = PML.ps_blocks ps' ++ LBo /\ LBk = LBo /\ W = Wf P E /\ PMLA.pcredit_xA L cr' ps' kx bx /\ Rel ps ps' code R').

(* [comment removed for export] *)
Definition ptgx (WFin : PML.pstate -> Prop) (BBin : PML.pstate -> Z -> Prop) (PAin : mem -> Z -> PML.pstate -> Prop) (PAout : PML.pstate -> mem -> Z -> PML.pstate -> Prop)
    (pc scr d : Z) (uar : bool) (Args : bvmap 5 word -> mem -> list (Z * Z) -> Z -> Z -> Z -> PML.pstate -> PMES.eghost -> Prop)
    (Rel : PML.pstate -> PML.pstate -> Z -> bvmap 5 word -> Prop) (Wf : Z -> Z -> Z -> Z -> list L5.range) : Prop :=
  forall (LBo : list (Z * Z)) (FF LK : list fframe) (cr : credit) (A : list (Z * Z)) (sp r P V E S2 B kx bx : Z) (g : PML.ls_state) (ps : PML.pstate) (eg : PMES.eghost),
    PMSA.cps_asan L ar HI pc r sp scr (PML.ps_blocks ps ++ LBo ++ PMES.g_lbv eg) FF LK cr A d
      (fun R M => Args R M LBo P V E ps eg /\ (uar = true -> sp mod 32 = 0) /\ PMSA.stksh ar M sp scr /\
                  PAin M P ps /\ PMSA.parser_sh M ps /\ WFin ps /\ PMSA.win_okA M LBo ps /\ BBin ps B /\ PMSA.vis_at L IC M V /\ PMSA.ec_at L IC M E 0 /\ PMSA.ls_ok L IC g M /\ g <> PML.LS0 /\
                  (PSOIW.ienc_invA I) M V S2 eg /\ PMXA.lits_ok L IC M /\ PMXA.enc_sync ps eg /\
                  0 <= kx /\ 0 <= bx /\ PMLA.pcredit_xA L cr ps (kx + PMXA.kenc L eg) (bx + (PSOIW.ibenc I) eg) /\
                  PMSA.fobj M FF P 272 /\ PMSA.fobj M FF V PMES.ENC_SIZE /\ PMSA.fobj M FF E 16 /\ PMSA.fobj M FF S2 24 /\
                  PMLA.apart P 272 V PMES.ENC_SIZE /\ PMLA.apart P 272 E 16 /\ PMLA.apart V PMES.ENC_SIZE E 16 /\
                  PMLA.apart P 272 S2 24 /\ PMLA.apart V PMES.ENC_SIZE S2 24 /\ PMLA.apart S2 24 E 16)
      (fun R M R' M' LB' cr' LBk W => exists (ps' : PML.pstate) (code : Z) (g' : PML.ls_state) (eg' : PMES.eghost),
          PAout ps M' P ps' /\ PMSA.parser_sh M' ps' /\ PML.wf_ps ps' /\ PMSA.win_okA M' LBo ps' /\ PML.buf_bound ps' B /\ PMSA.ec_at L IC M' E code /\ (code <> 0 -> PML.ps_more ps' = false) /\
          PMSA.ls_ok L IC g' M' /\ (g' = g \/ (g' = PML.LS2 /\ code <> 0)) /\
          (PSOIW.ienc_invA I) M' V S2 eg' /\ PMXA.lits_ok L IC M' /\ (code = 0 -> PMXA.enc_sync ps' eg') /\
          LB' = PML.ps_blocks ps' ++ LBo ++ PMES.g_lbv eg' /\ LBk = LBo /\ W = Wf P V E S2 /\
          PMLA.pcredit_xA L cr' ps' (kx + PMXA.kenc L eg') (bx + (PSOIW.ibenc I) eg') /\ Rel ps ps' code R').
