Definition ptgw (f : PMW.fname) (MIn : PMR.ctrl -> mem -> Z -> PML.pstate -> Prop) (inp_of : PML.pstate -> list Z -> list Z -> list Z) (WFin : PML.pstate -> Prop) (BBin : PML.pstate -> Z -> Prop) (PAin : mem -> Z -> PML.pstate -> Prop) (PAout : PML.pstate -> mem -> Z -> PML.pstate -> Prop)
    (pc scr d : Z) (uar : bool) (Args : bvmap 5 word -> mem -> list (Z * Z) -> Z -> Z -> Z -> PML.pstate -> list Z -> Prop)
    (Rel : PML.pstate -> PML.pstate -> Z -> bvmap 5 word -> Prop) (Wf : Z -> Z -> list L5.range) : Prop :=
  forall (LBo : list (Z * Z)) (FF LK : list fframe) (cr : credit) (A : list (Z * Z)) (sp r P V E B kx bx : Z) (g : PML.ls_state) (ps : PML.pstate) (w x : list Z) (c : PMR.ctrl),
    PMSA.cps_asan L ar HI pc r sp scr (PML.ps_blocks ps ++ LBo) FF LK cr A d
      (fun R M => Args R M LBo P V E ps x /\ (uar = true -> sp mod 32 = 0) /\ PMSA.stksh ar M sp scr /\
                  PAin M P ps /\ PMSA.parser_sh M ps /\ WFin ps /\ PMSA.win_okA M LBo ps /\ BBin ps B /\ PMSA.vis_at L IC M V /\ PMSA.ec_at L IC M E 0 /\
                  PMSA.ls_ok L IC g M /\ g <> PML.LS0 /\
                  PMLA.pcredit_xA L cr ps kx bx /\ PMSA.fobj M FF P 272 /\ PMSA.fobj M FF V 8 /\ PMSA.fobj M FF E 16 /\
                  PMLA.apart P 272 V 8 /\ PMLA.apart P 272 E 16 /\ PMLA.apart V 8 E 16 /\
                  PMXAW.win_bytesA L M ps w /\ MIn c M P ps)
      (fun R M R' M' LB' cr' LBk W => exists (ps' : PML.pstate) (code : Z) (g' : PML.ls_state),
          PAout ps M' P ps' /\ PMSA.parser_sh M' ps' /\ PML.wf_ps ps' /\ PMSA.win_okA M' LBo ps' /\ PML.buf_bound ps' B /\ PMSA.ec_at L IC M' E code /\
          (code <> 0 -> PML.ps_more ps' = false) /\
          PMSA.ls_ok L IC g' M' /\ (g' = g \/ (g' = PML.LS2 /\ code <> 0)) /\
          LB' = PML.ps_blocks ps' ++ LBo /\ LBk = LBo /\ W = Wf P E /\ PMLA.pcredit_xA L cr' ps' kx bx /\ Rel ps ps' code R' /\
          let rr := PMW.rm_step (PMRXA.the_rmA L) f c (inp_of ps w x) in
          code = PMW.r_code rr /\ PMW.r_evs rr = [] /\
          (code = 0 -> PMW.rm_match (PMRXA.the_rmA L) (PMW.r_ctrl rr) M' P ps' /\ PMW.r_used rr = PML.winlen ps - PML.winlen ps' /\ PMXAW.win_bytesA L M' ps' (PMW.w_after (PMRXA.the_rmA L) rr w))).
