                 (PSO.curk (PSO.KPt pc) = true /\ exists pm pn e, mw3 = Some (pm, e) /\ PML.ps_win ps3 = Some (pn, e) /\ pm <= pn /\ CL5A.uv E2 (PSOX.a0reg j) = pn).
Hypothesis HWIN3 : PSOX.WIN I ps3.
Hypothesis HG3 : g' = g \/ (g' = PML.LS2 /\ code <> 0).
Hypothesis HLS3 : PMLA.ls_ok (hl_segs L) IC g' M2.
Hypothesis HCM3 : code <> 0 -> PML.ps_more ps3 = false.
Hypothesis HPTR : PSOX.PTR pc ps3 code.
Hypothesis HU0 : PSO.u0 j = PSO.u0 i.
Hypothesis HNA : PSO.u0 i = false -> PSOIW.st0 I <> PML.ST_ACCEPT.
Hypothesis HWLn : PSO.u0 i = false -> 1 <= PSOIW.wlen I.
Hypothesis HE0 : PSO.u0 i = true -> env_agree 60 E0 E1.
Hypothesis HMEAS : forall X, In X (PSOK.MEASNEWS (SR.ps_cells ps0)) -> exists e lo hi, X = KRange e lo hi /\ APC.expr_vars_lt gx e = true /\ lo <= CL5A.uv E' e <= hi.

