Record PREWF (i : nat) (ps1 : PML.pstate) : Prop := MKPW {
  pw_wf : PSO.kind_of i <> PSO.KVpush -> PML.wf_ps ps1;
  pw_vp : PSO.kind_of i = PSO.KVpush -> exists stk, PML.ps_stack ps1 = stk ++ [PSOX.vpx i] /\ (length stk <= 1026)%nat /\
        PML.wf_ps (PML.PS (PML.ps_st ps1) (PML.ps_sst ps1) (PML.ps_nst ps1) true (PML.ps_done ps1) (PML.ps_level ps1) stk (PML.ps_sb ps1) (PML.ps_scap ps1)
                          (PML.ps_bcap ps1) (PML.ps_bptr ps1) (PML.ps_buf ps1) (PML.ps_win ps1)) /\
        ((PML.is_expect (PML.ps_st ps1) /\ PSOX.vpx i = PML.ps_st ps1) \/ (PML.ps_st ps1 = PML.ST_SLASH_STAR /\ PSOX.vpx i = PML.ST_SLASH_STAR) \/
         ((PML.ps_st ps1 = PML.ST_EXPECT_MEMBER_NAME_OR_END \/ PML.ps_st ps1 = PML.ST_EXPECT_MEMBER_NAME) /\ PSOX.vpx i = PML.ST_MEMBER_NAME));
