(* [comment removed for export] *)
Record LST (i : nat) (E1 E' : env) (M' : mem) (l : PSO.pv) (ps1 ps2 : PML.pstate) (g1 : PML.ls_state) (z : Z) : Prop := MKLST {
  ls_core : PSOX.CORE I i E1 M' (PML.ps_win ps2) ps2 0 g1;
  ls_wf : PML.wf_ps ps2;
  ls_more : PML.ps_more ps2 = true;
  ls_st : PML.ps_st ps2 = z;
  ls_cur : PSOIW.wlo (PML.ps_win ps2) = CL5A.uv E' (PSO.v_wptr l);
  ls_win : match PML.ps_win ps1 with Some (p, e) => exists p', PML.ps_win ps2 = Some (p', e) /\ p <= p' <= p + 1 | None => PML.ps_win ps2 = None end;
  ls_nst : Z_to_bv 8 (CL5A.uv E' (PSO.v_nst l)) = Z_to_bv 8 (PML.ps_nst ps2) }.

(* [comment removed for export] *)
Record LSTW (i : nat) (c : CC.cutpoint) (cells : list kentry) (t l : PSO.pv) (ps1 ps2 : PML.pstate) : Prop := MKLSTW {
  lw_up : ps2 = PSOST.ps_upd ps1 (PML.ps_st ps2) (PML.ps_sst ps2) (PML.ps_nst ps2) true (PML.ps_done ps1) (PML.ps_buf ps2) (PML.ps_win ps2);
  lw_more1 : PML.ps_more ps1 = true;
  lw_win : PML.ps_win ps2 = match PML.ps_win ps1 with Some (p, e) => Some (p + PADV i cells t l, e) | None => None end;
  lw_cls : match PSO.pclass i c cells t l (PSO.mkdelta cells t l) with
           | Some PSO.PSame => PML.ps_st ps2 = PML.ps_st ps1 /\ PML.ps_sst ps2 = PML.ps_sst ps1 /\ PML.ps_nst ps2 = PML.ps_nst ps1 /\
                               (PSO.d_size (PSO.mkdelta cells t l) = PSO.Same -> PSO.has_bufbyte (CC.cp_F c) = false -> PML.ps_buf ps2 = PML.ps_buf ps1)
           | Some (PSO.PString _) => PML.ps_st ps2 = PML.ST_STRING /\ PML.ps_sst ps2 = 0 /\ PML.ps_buf ps2 = []
           | Some (PSO.PNumber _ n) => PML.ps_st ps2 = PML.ST_NUMBER /\ PML.ps_nst ps2 = n /\
                                      exists c0 lo hi, PML.ps_buf ps1 = [c0] /\ PML.ps_buf ps2 = [c0 mod 256] /\ PSO.byte_rng cells l = Some (lo, hi) /\ lo <= c0 mod 256 <= hi
           | None => False end }.
