(* [comment removed for export] *)
Lemma PNUM : forall pc i c k ps0 E1 R1 A1 M1 m1 E' R' M' m' ps1 g1 t l s1 n pq e c0,
  CH2.is_leaf G.CPS G.TAGS i c k ps0 (CC.TOther pc) -> In pc PT -> PSO.dead_chk i ps0 pc = false -> PSO.pre_chk i c ps0 pc = true -> pt_leaf i c ps0 pc = true ->
  PSO.pview (CC.cp_know c) = Some t -> PSO.pview (SR.ps_cells ps0) = Some l ->
  PSO.pclass i c (SR.ps_cells ps0) t l (PSO.mkdelta (SR.ps_cells ps0) t l) = Some (PSO.PNumber s1 n) -> PSO.d_adv (PSO.mkdelta (SR.ps_cells ps0) t l) = 1 ->
  (2 <= i < PSO.NCUT)%nat -> PSO.curk (PSO.kind_of i) = false ->
  CCA.AtV (hl_segs L) c E1 R1 A1 M1 m1 -> AAMB I i E1 A1 M1 m1 -> env_agree (CC.cp_nx c) E1 E' -> CCA.leaf_factsA (hl_segs L) c ps0 E' R' A1 M1 m1 M' m' ->
