(* [comment removed for export] *)
Definition WK (f : PMW.fname) (j : nat) (ps2 : PML.pstate) (cw : PMR.ctrl) (inp : list Z) : Prop :=
  forall (eg' : PMES.eghost) (M2 : mem) (ps3 psx : PML.pstate) (code : Z),
    let rr := PMR.rstep f cw inp in
    code = PMW.r_code rr ->
    ((PMES.g_es eg' = PMW.es_run (PMES.g_es (PSOIW.ig1 I)) (PMW.r_evs rr) /\
      exists pay, 0 <= pay <= PMW.r_allow rr /\ PMES.g_len eg' = PMES.g_len (PSOIW.ig1 I) + PMW.ind_run (PMES.g_es (PSOIW.ig1 I)) (PMW.r_evs rr) + pay)
     \/ (eg' = (PSOIW.ig1 I) /\ PMW.r_evs rr = [])) ->
    (code = 0 -> PMRXA.rm_matchA L (PMW.r_ctrl rr) M2 P ps3 /\ PMW.r_used rr = PML.winlen ps2 - PML.winlen ps3) ->
    PSOX.WIN I ps3 -> PMLA.parser_at (hl_segs L) IC M2 P psx ->
    WPT eg' j M2 ps3 code.
(* [comment removed for export] *)
Definition WCALL (f : PMW.fname) (inp_of : PML.pstate -> list Z -> list Z -> list Z) (j : nat) (Mx : mem) (ps2 : PML.pstate) : Prop :=
  exists (w x : list Z) (cw : PMR.ctrl),
    PMXAW.win_bytesA L Mx ps2 w /\ PMRXA.rm_matchA L cw Mx P ps2 /\
    PMXAW.wroomr (PMRXA.the_rmA L) (PSOIW.iCLA I) (PSOIW.ig1 I) (PMW.rm_step (PMRXA.the_rmA L) f cw (inp_of ps2 w x)) /\ WK f j ps2 cw (inp_of ps2 w x).

(* [comment removed for export] *)
Lemma PTW_intro : forall (eg' : PMES.eghost) j cc b r evs al q (M2 : mem) ps3 psx code,
  PMRF.hreach (PSOX.c0 I) (PSOX.w0 I) cc (b :: r) evs al -> PMR.c_more cc = true -> PMR.iter cc b r = q -> code = PMR.q_code q ->
  PSOX.SYNC (PSOIW.setg I eg') (evs ++ PMR.q_evs q) (al + PMR.q_al q) ->
  (code = 0 -> PMRXA.rm_matchA L (PMR.q_c q) M2 P ps3 /\ PMR.q_w q = PSOX.rem I ps3 (PSOX.PTOFF j) /\
               (PSOX.PTOFF j = 1 -> PMR.c_st (PMR.q_c q) <> PML.ST_STRING /\ PMR.c_st (PMR.q_c q) <> PML.ST_NUMBER)) ->
  PMLA.parser_at (hl_segs L) IC M2 P psx ->
