Definition cfn (a : PMR.act) : option PMW.fname :=
  match a with
  | PMR.ASkip => Some PMW.FSkipSpace | PMR.ABegin arr => Some (if arr then PMW.FBeginArray else PMW.FBeginObject)
  | PMR.AEnd arr => Some (if arr then PMW.FEndArray else PMW.FEndObject) | PMR.AString _ => Some PMW.FParseString | PMR.ANumber => Some PMW.FParseNumber
  | PMR.ALit which => Some (if which =? 0 then PMW.FParseNull else if which =? 1 then PMW.FParseTrue else PMW.FParseFalse)
  | PMR.AComma => Some PMW.FBeginMember | PMR.AParseString => Some PMW.FParseString | PMR.AParseNumber => Some PMW.FParseNumber | _ => None end.
