(* [comment removed for export] *)
Lemma LW_same : forall ps1 ps2,
  ps2 = PSOST.ps_upd ps1 (PML.ps_st ps2) (PML.ps_sst ps2) (PML.ps_nst ps2) true (PML.ps_done ps1) (PML.ps_buf ps2) (PML.ps_win ps2) ->
  PML.ps_more ps2 = true /\ PML.ps_done ps2 = PML.ps_done ps1 /\ PML.ps_level ps2 = PML.ps_level ps1 /\ PML.ps_stack ps2 = PML.ps_stack ps1.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S90!1'jS#3!8'r2#3!1'gU#2!1'jP#2!1'jQ#2,D0!1'gW#2!1'kL#2!1+6+0!3+S+900!1'jT#3!3+S+044!1'gR#3!3+S266!2+_P57$ps1;R+`S$ps2;R+`S$EQ;R!3+S+`S#1!8'r2#2!1'gU#1!1'jP#1!1'jQ#1,D!1'jS#2!1'gW#1!1'kL#1!6'^1+`S1$ps2;R+`S!2+_P!3+S+9!1'f4#1,D!2+_P!3+S+9!1'jS#1!1'jS#4!2+_P!3+S+0!1'jT#1!1'jT#4!3+S2!1'gR#1!1'gR#4vd!4,_S!3+S+9,D,D!2+_P38!2,^2+9,D!4,_S38!2,^2+90!4,_S57!2,^2+04!2,^226!2+_P!3+S+9!1'f41,D!2+_P!3+S+9!1'jS10!2+_P!3+S+0!1'jT14!3+S2!1'gR16#2#1").
Qed.

(* [comment removed for export] *)
Lemma CALLW_CSL : forall f tg i c k ps0 t l E1 R1 A1 M1 m1 E' R' M' m' ps1 ps2 g1 z j st bv a,
  CH2.is_leaf G.CPS G.TAGS i c k ps0 tg -> (2 <= i < PSO.NCUT)%nat ->
  CCA.AtV (hl_segs L) c E1 R1 A1 M1 m1 -> AAMB I i E1 A1 M1 m1 -> env_agree (CC.cp_nx c) E1 E' -> CCA.leaf_factsA (hl_segs L) c ps0 E' R' A1 M1 m1 M' m' ->
  PSOCK.AKAG I M' -> PSO.pview (CC.cp_know c) = Some t -> PSO.pview (SR.ps_cells ps0) = Some l ->
  PSO.kind_of i = PSO.KCsl ->
  PSOX.CORE I i E1 M1 (PML.ps_win ps1) ps1 0 g1 -> PML.wf_ps ps1 -> PSOX.WCORE I i E1 M1 ps1 0 ->
  LST i E1 E' M' l ps1 ps2 g1 z -> LSTW i c (SR.ps_cells ps0) t l ps1 ps2 ->
  PSOWK2.ldec c (SR.ps_cells ps0) (PSOWT.woff i) (PSOWT.ppv i) = Some (st, bv, a) -> PSOWT.woff i = 0 -> PSOWK2.ntok st = true ->
  cfn a = Some f -> cadv a = PADV i (SR.ps_cells ps0) t l -> PSOX.PTOFF j = ccomma a ->
  match PSO.pclass i c (SR.ps_cells ps0) t l (PSO.mkdelta (SR.ps_cells ps0) t l) with
  | Some PSO.PSame => (forall key, a <> PMR.AString key) /\ a <> PMR.ANumber
  | Some (PSO.PString _) => a = PMR.AString false /\ exists tz, PMSA.u8 L M' (P + 220) tz /\ 0 <= tz <= 1
