(* [comment removed for export] *)
Lemma CALLW_H : forall f i c ps0 t l E1 R1 A1 M1 m1 E' R' M' m' ps1 ps2 g1 z j,
  nth_error G.CPS i = Some c -> (2 <= i < PSO.NCUT)%nat ->
  CCA.AtV (hl_segs L) c E1 R1 A1 M1 m1 -> AAMB I i E1 A1 M1 m1 -> env_agree (CC.cp_nx c) E1 E' -> CCA.leaf_factsA (hl_segs L) c ps0 E' R' A1 M1 m1 M' m' -> PSOX.FLF I E1 ->
  PSOCK.AKAG I M' -> PSO.pview (CC.cp_know c) = Some t -> PSO.pview (SR.ps_cells ps0) = Some l ->
  PSO.kind_of i = PSO.KH ->
  PSOX.CORE I i E1 M1 (PML.ps_win ps1) ps1 0 g1 -> PML.wf_ps ps1 -> PSOX.WCORE I i E1 M1 ps1 0 ->
  LST i E1 E' M' l ps1 ps2 g1 z -> LSTW i c (SR.ps_cells ps0) t l ps1 ps2 ->
  PSO.pclass i c (SR.ps_cells ps0) t l (PSO.mkdelta (SR.ps_cells ps0) t l) = Some PSO.PSame ->
  PSO.d_size (PSO.mkdelta (SR.ps_cells ps0) t l) = PSO.Same -> PSO.has_bufbyte (CC.cp_F c) = false -> existsb (PSO.region_eqb (PE, 220, ELit 1)) (CC.cp_F c) = false ->
  PADV i (SR.ps_cells ps0) t l = 0 -> PSO.v_wptr t = PSO.CURH -> PSO.lo_ge (CC.cp_know c) (EVar JV) 1 = true ->
