(* [comment removed for export] *)
Lemma CALLW_VP : forall i c ps0 t l E1 A1 M1 m1 E' R' M' m' ps1 ps2 g1 z j s1,
  nth_error G.CPS i = Some c -> (2 <= i < PSO.NCUT)%nat ->
  AAMB I i E1 A1 M1 m1 -> env_agree (CC.cp_nx c) E1 E' -> CCA.leaf_factsA (hl_segs L) c ps0 E' R' A1 M1 m1 M' m' ->
  PSOCK.AKAG I M' -> PSO.kind_of i = PSO.KVpush ->
  PSOX.CORE I i E1 M1 (PML.ps_win ps1) ps1 0 g1 -> PREWF i ps1 -> PSOX.WCORE I i E1 M1 ps1 0 ->
  LST i E1 E' M' l ps1 ps2 g1 z -> LSTW i c (SR.ps_cells ps0) t l ps1 ps2 ->
  PSO.pclass i c (SR.ps_cells ps0) t l (PSO.mkdelta (SR.ps_cells ps0) t l) = Some (PSO.PString s1) ->
  PSOWT.ract i = Some (PMR.AString true) -> PSOWT.woff i = -1 -> PSOX.vpx i = PML.ST_MEMBER_NAME -> PADV i (SR.ps_cells ps0) t l = 0 ->
