(* [comment removed for export] *)
Lemma CALLW : forall pc i c k ps0 t l E1 R1 A1 M1 m1 E' R' M' m' ps1 ps2 g1 z j cj,
  CH2.is_leaf G.CPS G.TAGS i c k ps0 (CC.TOther pc) -> In pc PT -> PSO.dead_chk i ps0 pc = false ->
  PSO.pview (CC.cp_know c) = Some t -> PSO.pview (SR.ps_cells ps0) = Some l -> PSO.ret_of i k = Some (j, cj) ->
  lit2 i c (SR.ps_cells ps0) t l (PSO.mkdelta (SR.ps_cells ps0) t l) = Some z ->
  (2 <= i < PSO.NCUT)%nat -> nth_error G.CPS i = Some c ->
  CCA.AtV (hl_segs L) c E1 R1 A1 M1 m1 -> AAMB I i E1 A1 M1 m1 -> env_agree (CC.cp_nx c) E1 E' -> CCA.leaf_factsA (hl_segs L) c ps0 E' R' A1 M1 m1 M' m' ->
  PSOCK.AKAG I M' -> PSOX.FLF I E1 ->
  (exists mw1, PSOX.CORE I i E1 M1 mw1 ps1 0 g1) -> PSOX.WCORE I i E1 M1 ps1 0 -> PREWF i ps1 ->
