(* [comment removed for export] *)
Section GEN.
Variables (fn : PMW.fname) (MIn : PMR.ctrl -> mem -> Z -> PML.pstate -> Prop) (inp_of : PML.pstate -> list Z -> list Z -> list Z).      (* [comment removed for export] *)
Variables (WFin : PML.pstate -> Prop) (BBin : PML.pstate -> Z -> Prop) (PAin : option (Z * Z) -> mem -> Z -> PML.pstate -> Prop)
          (PAout : option (Z * Z) -> PML.pstate -> mem -> Z -> PML.pstate -> Prop) (pc scr dd : Z) (uar : bool) (Args : bvmap 5 word -> mem -> list (Z * Z) -> Z -> Z -> Z -> PML.pstate -> list Z -> Prop)
          (Rel : PML.pstate -> PML.pstate -> Z -> bvmap 5 word -> Prop) (Wf : Z -> Z -> list L5.range).
(* [comment removed for export] *)
Hypothesis SPEC : forall mw, ptgw fn MIn inp_of WFin BBin (PAin mw) (PAout mw) pc scr dd uar Args Rel Wf.
Hypothesis HMIN : forall cw (Mx : mem) psx, PMRXA.rm_matchA L cw Mx P psx -> MIn cw Mx P psx.      (* [comment removed for export] *)
Hypothesis HPT : In pc PT.
Variable xa : CAXA.xsumA.
Hypothesis Hxs : PSOK.xs_at pc = Some xa.
Hypothesis XSCR : CAX.xs_scr (PSOK.x_of xa) = scr.
Hypothesis XNG : CAX.xs_ng (PSOK.x_of xa) = 14%nat.
Hypothesis XKEEP : forall regs BL, CAX.xs_keep (PSOK.x_of xa) regs BL = [].
Hypothesis XDD : 0 <= dd <= 5.
Hypothesis XSCR8 : scr mod 8 = 0 /\ 0 <= scr /\ 672 + scr <= 17600.
Hypothesis XBLK : forall regs cells g0, PSOK.blk_of xa regs cells g0 [] = [(EVar (g0 + 10), APC.escale 2 (EVar (g0 + 8))); (EVar (g0 + 11), EVar (g0 + 13))].
Variables (xw : list kentry -> nat -> expr) (WFf : list expr -> list kentry -> nat -> list kentry) (EXf : nat -> list kentry).
Hypothesis XNEWS : forall regs cells g0, PSOK.news_of xa regs cells g0 [] = NEWS cells (xw cells g0) (WFf regs cells g0) (EXf g0) g0.
Hypothesis XWR : forall regs (Ex : env), CL5A.uv Ex (EVar 10) = P -> CL5A.uv Ex (EVar 12) = E ->
  forall w a, In w (Wf P E) -> L5.in_rng w a -> exists r, In r (CAX.xs_wregs (PSOK.x_of xa) regs) /\ CHA.in_reg Ex r a.
Hypothesis XWW : incl (Wf P E) WW.
Hypothesis XWX : forall w, In w (Wf P E) -> w = (P, 272) \/ w = (E, 16) \/ (65536 <= fst w /\ fst w + snd w <= 7094272 /\ (fst w + snd w <= 6946376 \/ 6946448 <= fst w)).      (* [comment removed for export] *)

(* [comment removed for export] *)
Record RETX (j gx : nat) (cells : list kentry) (regs : list expr) (E' : env) (R2 : bvmap 5 word) (M2 : mem) (A2 : list (Z * Z)) (m2 : Model)
            (ps2 ps3 : PML.pstate) (code : Z) (mw3 : option (Z * Z)) (d1 : Z) : Prop := MKRX {
  rx_pa : PMLA.parser_at (hl_segs L) IC M2 P (PML.ps_set_win ps3 mw3);
  rx_d1 : 0 <= d1 < 2 ^ 64;
  rx_nr : PMSA.not_retreated ps2 ps3;
  rx_ptr : PSOX.PTR pc ps3 code;
  rx_mw : (PSO.curk (PSO.KPt pc) = false /\ mw3 = PML.ps_win ps3) \/
          (PSO.curk (PSO.KPt pc) = true /\ exists pm pn e, mw3 = Some (pm, e) /\ PML.ps_win ps3 = Some (pn, e) /\ pm <= pn /\
                                               CL5A.uv (CH2.retEx E' gx (ghosts ps3 code d1) R2) (PSOX.a0reg j) = pn);
  rx_a0 : match CAX.xs_a0 (PSOK.x_of xa) regs gx with Some e => getr R2 10%bv = edenot (CH2.retEx E' gx (ghosts ps3 code d1) R2) e | None => True end;
  rx_xw : CL5A.uv (CH2.retEx E' gx (ghosts ps3 code d1) R2) (xw cells gx) = PSOIW.wlo mw3;
  rx_wf : Forall (kentry_ok (hl_segs L) (CH2.retEx E' gx (ghosts ps3 code d1) R2) (CCA.vis A2 m2 M2)) (WFf regs cells gx);
  rx_ex : Forall (kentry_ok (hl_segs L) (CH2.retEx E' gx (ghosts ps3 code d1) R2) (CCA.vis A2 m2 M2)) (EXf gx) }.

Hypothesis CB : forall i c k ps0 j cj gx t l E1 R1 A1 M1 m1 E' R' M' m' ps1 ps2 g1 z,
  CH2.is_leaf G.CPS G.TAGS i c k ps0 (CC.TOther pc) -> PSO.dead_chk i ps0 pc = false -> pt_leaf i c ps0 pc = true -> PSO.pre_chk i c ps0 pc = true ->
  PSO.pview (CC.cp_know c) = Some t -> PSO.pview (SR.ps_cells ps0) = Some l -> PSO.ret_of i k = Some (j, cj) ->
  lit2 i c (SR.ps_cells ps0) t l (PSO.mkdelta (SR.ps_cells ps0) t l) = Some z ->
  CCA.AtV (hl_segs L) c E1 R1 A1 M1 m1 ->      (* [comment removed for export] *)
  AAMB I i E1 A1 M1 m1 -> env_agree (CC.cp_nx c) E1 E' -> CCA.leaf_factsA (hl_segs L) c ps0 E' R' A1 M1 m1 M' m' -> know_ok (hl_segs L) E1 (CCA.vis A1 m1 M1) (CC.cp_know c) ->
  (CC.cp_nx c <= gx)%nat ->
  (2 <= i < PSO.NCUT)%nat -> nth_error G.CPS i = Some c -> nth_error G.CPS j = Some cj -> (2 <= j < PSO.NCUT)%nat -> PSO.kind_of j = PSO.KPt pc ->
  CC.cp_nx cj = (gx + 14 + APC.NCS)%nat ->
  LST i E1 E' M' l ps1 ps2 g1 z ->
  PSOCK.AKAG I M' -> PSOX.FLF I E1 -> (exists mw1, PSOX.CORE I i E1 M1 mw1 ps1 0 g1) -> PSOX.WCORE I i E1 M1 ps1 0 -> PREWF i ps1 -> LSTW i c (SR.ps_cells ps0) t l ps1 ps2 ->      (* [comment removed for export] *)
  ((forall x, Args R' M' LBV P V E ps2 x) /\ PAin (PML.ps_win ps2) M' P ps2 /\ WFin ps2 /\ BBin ps2 B /\ WCALL fn inp_of j M' ps2) /\      (* [comment removed for export] *)
  (forall R2 M2 A2 m2 ps3 code, PAout (PML.ps_win ps2) ps2 M2 P ps3 -> Rel ps2 ps3 code R2 -> PML.wf_ps ps3 -> (code <> 0 -> PML.ps_more ps3 = false) ->
     PMLA.ec_at (hl_segs L) IC M2 E code -> PML.buf_bound ps3 B ->
     (exists mw3 d1, RETX j gx (SR.ps_cells ps0) (CA.ps_reglist ps0) E' R2 M2 A2 m2 ps2 ps3 code mw3 d1) /\ (code = 0 -> PMXA.enc_sync ps3 (PSOIW.ig1 I))).      (* [comment removed for export] *)

