(* [comment removed for export] *)
Section GENX.
Variables (fn : PMW.fname) (MIn : PMR.ctrl -> mem -> Z -> PML.pstate -> Prop) (inp_of : PML.pstate -> list Z -> list Z -> list Z).      (* [comment removed for export] *)
Variables (WFin : PML.pstate -> Prop) (BBin : PML.pstate -> Z -> Prop) (PAin : option (Z * Z) -> mem -> Z -> PML.pstate -> Prop)
          (PAout : option (Z * Z) -> PML.pstate -> mem -> Z -> PML.pstate -> Prop) (pc scr dd : Z) (uar : bool) (Args : bvmap 5 word -> mem -> list (Z * Z) -> Z -> Z -> Z -> PML.pstate -> PMES.eghost -> list Z -> Prop)
          (Rel : PML.pstate -> PML.pstate -> Z -> bvmap 5 word -> Prop) (Wf : Z -> Z -> Z -> Z -> list L5.range).
(* [comment removed for export] *)
Hypothesis SPEC : forall mw, ptgxw fn MIn inp_of WFin BBin (PAin mw) (PAout mw) pc scr dd uar Args Rel Wf.
Hypothesis HMIN : forall cw (Mx : mem) psx, PMRXA.rm_matchA L cw Mx P psx -> MIn cw Mx P psx.      (* [comment removed for export] *)
Hypothesis HPT : In pc PT.
Variable xa : CAXA.xsumA.
Hypothesis Hxs : PSOK.xs_at pc = Some xa.
Hypothesis XSCR : CAX.xs_scr (PSOK.x_of xa) = scr.
Hypothesis XNG : CAX.xs_ng (PSOK.x_of xa) = 14%nat.
Hypothesis XKEEP : forall regs BL, CAX.xs_keep (PSOK.x_of xa) regs BL = [].
Hypothesis XDD : 0 <= dd <= 10.
Hypothesis XSCR8 : scr mod 8 = 0 /\ 0 <= scr /\ 672 + scr <= 17600.
Hypothesis XBLK : forall regs cells g0, PSOK.blk_of xa regs cells g0 [] = [(EVar (g0 + 10), APC.escale 2 (EVar (g0 + 8))); (EVar (g0 + 11), EVar (g0 + 13))].
Variables (xw : list kentry -> nat -> expr) (WFf : list expr -> list kentry -> nat -> list kentry) (EXf : nat -> list kentry).
Hypothesis XNEWS : forall regs cells g0, PSOK.news_of xa regs cells g0 [] = NEWS cells (xw cells g0) (WFf regs cells g0) (EXf g0) g0.
Hypothesis XWR : forall regs (Ex : env), CL5A.uv Ex (EVar 10) = P -> CL5A.uv Ex (EVar 12) = E -> CL5A.uv Ex (EVar 11) = V -> CL5A.uv Ex (EVar 37) = SQ ->
  forall w a, In w (Wf P V E SQ) -> L5.in_rng w a -> exists r, In r (CAX.xs_wregs (PSOK.x_of xa) regs) /\ CHA.in_reg Ex r a.
Hypothesis XWW : incl (Wf P V E SQ) WW.


Hypothesis CB : forall i c k ps0 j cj gx t l E1 R1 A1 M1 m1 E' R' M' m' ps1 ps2 g1 z,
  CH2.is_leaf G.CPS G.TAGS i c k ps0 (CC.TOther pc) -> PSO.dead_chk i ps0 pc = false -> pt_leaf i c ps0 pc = true -> PSO.pre_chk i c ps0 pc = true ->
  PSO.pview (CC.cp_know c) = Some t -> PSO.pview (SR.ps_cells ps0) = Some l -> PSO.ret_of i k = Some (j, cj) ->
  lit2 i c (SR.ps_cells ps0) t l (PSO.mkdelta (SR.ps_cells ps0) t l) = Some z ->
  CCA.AtV (hl_segs L) c E1 R1 A1 M1 m1 ->      (* [comment removed for export] *)
  AAMB I i E1 A1 M1 m1 -> env_agree (CC.cp_nx c) E1 E' -> CCA.leaf_factsA (hl_segs L) c ps0 E' R' A1 M1 m1 M' m' -> know_ok (hl_segs L) E1 (CCA.vis A1 m1 M1) (CC.cp_know c) ->
  (CC.cp_nx c <= gx)%nat ->
