(* [comment removed for export] *)
Lemma CURSOR : forall i c E1 A1 M1 m1 E' l, nth_error G.CPS i = Some c -> (2 <= i < PSO.NCUT)%nat -> AAMB I i E1 A1 M1 m1 -> env_agree (CC.cp_nx c) E1 E' ->
