Lemma CUR_POST : forall pc xa i c ps0 j cj gx t l E1 A1 M1 m1 E' M' ps1 ps2 g1 z R2 M2 A2 m2 ps3 code dl,
  nth_error G.CPS i = Some c -> PSO.pre_chk i c ps0 pc = true ->
  PSO.pview (CC.cp_know c) = Some t -> PSO.pview (SR.ps_cells ps0) = Some l ->
  (2 <= i < PSO.NCUT)%nat -> AAMB I i E1 A1 M1 m1 -> env_agree (CC.cp_nx c) E1 E' -> (CC.cp_nx c <= gx)%nat ->
  nth_error G.CPS j = Some cj -> (2 <= j < PSO.NCUT)%nat -> PSO.kind_of j = PSO.KPt pc -> CC.cp_nx cj = (gx + 14 + APC.NCS)%nat ->
  LST i E1 E' M' l ps1 ps2 g1 z ->
  PSOK.xs_at pc = Some xa -> PSO.is_curpc pc = true -> (forall regs g0, CAX.xs_a0 (PSOK.x_of xa) regs g0 = Some (XA0_condBm g0)) ->
  (PSO.v_wptr l = PSO.CURH /\ dl = 0 \/ PSO.v_wptr l = EAlu Instr.ALU_ADD PSO.CURH (ELit 1) /\ dl = 1) ->
  0 <= CL5A.uv E1 (EVar JV) <= 16384 ->
  PMLA.parser_at (hl_segs L) IC M2 P (PML.ps_set_win ps3 (PML.ps_win ps2)) -> PMSA.not_retreated ps2 ps3 -> (exists p e, PML.ps_win ps3 = Some (p, e) /\ PMSA.a0 R2 p) ->
