           (ps2 : PML.pstate) (z : Z) : Prop := MKCBF {
  cb_ok : callee_ok pc ps0 (SR.ps_cells ps0) t l (PSO.mkdelta (SR.ps_cells ps0) t l) z = true;
  cb_z : 1 <= z <= 28;
  cb_reg : forall q e0, CL.ps_reg_is ps0 q e0 = true -> getr R' (Z_to_bv 5 (Z.of_nat q)) = Z_to_bv 64 (CL5A.uv E' e0);
  cb_a0 : PMSA.a0 R' P;
  cb_P : CL5A.uv E' PE = P;
  cb_V : CL5A.uv E' VE = V;
  cb_E : CL5A.uv E' EE = E;
  cb_kl : know_ok (hl_segs L) E' (CCA.vis A1 m' M') (SR.ps_cells ps0);
  cb_pa : PMLA.parser_at (hl_segs L) IC M' P ps2;
  cb_bb : PML.buf_bound ps2 B;
  cb_jr : 0 <= CL5A.uv E1 (EVar JV) <= 16384;
  cb_46 : CL5A.uv E' (EVar JV) = CL5A.uv E1 (EVar JV);
  cb_win : PSO.u0 i = false -> PML.ps_win ps2 = Some (CL5A.uv E' (PSO.v_wptr l), PSOIW.we0 I) /\ PSOIW.wp0 I <= CL5A.uv E' (PSO.v_wptr l) <= PSOIW.we0 I }.
Lemma CBK : forall pc i c k ps0 t l E1 A1 M1 m1 E' R' M' m' ps1 ps2 g1 z,
  CH2.is_leaf G.CPS G.TAGS i c k ps0 (CC.TOther pc) -> pt_leaf i c ps0 pc = true ->
  PSO.pview (CC.cp_know c) = Some t -> PSO.pview (SR.ps_cells ps0) = Some l ->
  lit2 i c (SR.ps_cells ps0) t l (PSO.mkdelta (SR.ps_cells ps0) t l) = Some z ->
  AAMB I i E1 A1 M1 m1 -> env_agree (CC.cp_nx c) E1 E' -> CCA.leaf_factsA (hl_segs L) c ps0 E' R' A1 M1 m1 M' m' ->
  know_ok (hl_segs L) E1 (CCA.vis A1 m1 M1) (CC.cp_know c) ->
  (2 <= i < PSO.NCUT)%nat -> nth_error G.CPS i = Some c -> LST i E1 E' M' l ps1 ps2 g1 z ->
  CBF pc i c ps0 t l E1 E' R' A1 m' M' ps2 z.
